// Normalise both feeds into one shape, then score against a profile.
// Profile: Node/TypeScript backend, AI/LLM integration, remote-from-Serbia or Novi Sad/Belgrade.
const PROFILE = {
  // Must read as an engineering seat before anything else counts.
  titleGate: /\b(developer|engineer|programmer|architect)\b/i,
  stack:   [/\bnode(\.js)?\b/i, /typescript/i, /backend|back-end/i, /postgres/i, /\baws\b|azure/i, /\bllm\b|\bmcp\b|agentic|gen(erative)?\s*ai|ai[- ](engineer|integration|native|agent)/i, /react|next\.js/i, /full[- ]?stack/i],
  geoGood: [/anywhere|worldwide|global/i, /europe|emea|\bcet\b/i, /serbia|belgrade|novi sad/i],
  // Title-level: roles that are not an individual-contributor backend seat.
  titleBlock: [/\b(manager|lead|head|director|principal|staff|vp|cto)\b/i, /\b(ios|android|mobile|qa|devops|sre|data engineer|ml engineer)\b/i, /\b(java|c#|\.net|golang|\bgo\b|php|ruby|python)\b(?!script)/i],
  // Body-level hard blockers: years bars he cannot meet, residency clauses.
  bodyBlock: [/\b([5-9]|1\d)\+?\s*(years|yrs)\b[^.]{0,40}\b(experience|exp)\b/i, /\bus[- ]only\b|united states only|must be (located|based) in the (us|eu)\b/i, /eu[- ]based candidates|eligible to work in the eu/i],
};
function score(title, text) {
  const why = [];
  if (!PROFILE.titleGate.test(title)) return { s: 0, why: 'not an engineering title' };
  for (const b of PROFILE.titleBlock) if (b.test(title)) return { s: 0, why: 'title-blocked' };
  for (const b of PROFILE.bodyBlock)  if (b.test(text))  return { s: 0, why: 'blocked: ' + b.source.slice(0, 25) };
  let s = 0;
  for (const r of PROFILE.stack)   if (r.test(text)) { s += 15; why.push(r.source.replace(/\\b/g,'').slice(0, 14)); }
  for (const g of PROFILE.geoGood) if (g.test(text)) { s += 10; why.push('geo:' + g.source.slice(0, 12)); }
  if (/\b(senior|sr\.?)\b/i.test(title)) s -= 10;           // apply anyway, rank lower
  return { s, why: why.join(', ') };
}
const strip = h => (h || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  if (Array.isArray(d.jobs) && d.jobs[0] && d.jobs[0].jobTitle) {   // Jobicy
    for (const j of d.jobs) out.push({ source: 'jobicy', title: j.jobTitle, company: j.companyName, url: j.url,
      location: j.jobGeo, posted: j.pubDate, text: `${j.jobTitle} ${j.companyName} ${j.jobGeo} ${strip(j.jobDescription)}` });
  } else if (Array.isArray(d.jobs)) {             // Remotive
    for (const j of d.jobs) out.push({ source: 'remotive', title: j.title, company: j.company_name, url: j.url,
      location: j.candidate_required_location, posted: j.publication_date,
      text: `${j.title} ${j.company_name} ${j.candidate_required_location} ${strip(j.description)}` });
  } else if (d.position) {                        // RemoteOK (first row is a legal notice with no position)
    out.push({ source: 'remoteok', title: d.position, company: d.company, url: d.url, location: d.location, posted: d.date,
      text: `${d.position} ${d.company} ${d.location} ${(d.tags || []).join(' ')} ${strip(d.description)}` });
  }
}
const seen = new Set();
return out
  .filter(j => j.title && !seen.has(j.url) && seen.add(j.url))
  .map(j => { const { s, why } = score(j.title, j.text); const { text, ...rest } = j; return { json: { ...rest, score: s, why } }; })
  .filter(j => j.json.score >= 30)
  .sort((a, b) => b.json.score - a.json.score)
  .slice(0, 15);

const rows = $input.all().map(i => i.json);
const digest = rows.map(j => `- [${j.score}] ${j.title} — ${j.company} (${j.location || 'remote'}) ${j.url} — ${j.why}`).join('\n');
return [{ json: { count: rows.length, digest } }];
